export type SignalboxUiWorkflowId = never;
export type SignalboxUiTransitionId = never;
export type SignalboxUiWorkflow = (typeof SignalboxUiManifest.workflows)[number];
export type SignalboxUiWorkflowTransition =
  SignalboxUiWorkflow extends { transitions: readonly (infer Transition)[] } ? Transition : never;

export interface SignalboxUiWorkflowStateById {

}

export interface SignalboxUiTransitionInputById {

}

export interface SignalboxUiTransitionResultById {

}

/** Return state-matching edges only. Authorization and preconditions remain server-enforced. */
export function availableSignalboxUiTransitions<Id extends SignalboxUiWorkflowId>(
  workflowId: Id,
  state: SignalboxUiWorkflowStateById[Id],
): readonly SignalboxUiWorkflowTransition[] {
  const workflows = SignalboxUiManifest.workflows as readonly {
    workflowId: string;
    transitions: readonly { fromValue: string }[];
  }[];
  const workflow = workflows.find((candidate) => candidate.workflowId === workflowId);
  if (!workflow) throw new ValidationError("Unknown ModelLang UI workflow", "ML_UI_WORKFLOW_NOT_FOUND", "ui:workflow");
  return workflow.transitions.filter((transition) => transition.fromValue === state) as unknown as readonly SignalboxUiWorkflowTransition[];
}

export interface SignalboxUiWorkflowExecutor {
  available<Id extends SignalboxUiWorkflowId>(
    workflowId: Id,
    state: SignalboxUiWorkflowStateById[Id],
  ): readonly SignalboxUiWorkflowTransition[];
  executeTransition<Id extends SignalboxUiTransitionId>(
    transitionId: Id,
    targetId: string,
    input: SignalboxUiTransitionInputById[Id],
    options?: ExecutionOptions,
  ): Promise<SignalboxUiTransitionResultById[Id]>;
  assessTransition<Id extends SignalboxUiTransitionId>(
    transitionId: Id,
    targetId: string,
    input: SignalboxUiTransitionInputById[Id],
    options?: ApplicabilityOptions,
  ): Promise<ApplicabilityDecision>;
}

/** Bind workflow targets and execute only declared transition actions through authenticated HTTP. */
export function createSignalboxUiWorkflowExecutor(
  client: SignalboxHttpClient,
): SignalboxUiWorkflowExecutor {
  return {
    available: availableSignalboxUiTransitions,
    async executeTransition<Id extends SignalboxUiTransitionId>(
      transitionId: Id,
      targetId: string,
      input: SignalboxUiTransitionInputById[Id],
      options: ExecutionOptions = {},
    ): Promise<SignalboxUiTransitionResultById[Id]> {
      switch (transitionId) {

        default:
          throw new ValidationError("Unknown ModelLang UI transition", "ML_UI_TRANSITION_NOT_FOUND", "ui:transition");
      }
    },
    async assessTransition<Id extends SignalboxUiTransitionId>(
      transitionId: Id,
      targetId: string,
      input: SignalboxUiTransitionInputById[Id],
      options: ApplicabilityOptions = {},
    ): Promise<ApplicabilityDecision> {
      switch (transitionId) {

        default:
          throw new ValidationError("Unknown ModelLang UI transition", "ML_UI_TRANSITION_NOT_FOUND", "ui:transition");
      }
    },
  };
}
